<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class TaxRate extends Model { protected $fillable=['public_id','tax_jurisdiction_id','tax_class_id','applies_to','label','rate_bps','status','valid_from','valid_until','metadata']; protected function casts():array{return ['rate_bps'=>'integer','valid_from'=>'datetime','valid_until'=>'datetime','metadata'=>'array'];} public function getRouteKeyName():string{return 'public_id';} public function jurisdiction(){return $this->belongsTo(TaxJurisdiction::class,'tax_jurisdiction_id');} public function taxClass(){return $this->belongsTo(TaxClass::class);} }